CREATE TABLE IF NOT EXISTS users ( id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at INTEGER NOT NULL ); CREATE TABLE IF NOT EXISTS sync ( user_id TEXT PRIMARY KEY, data TEXT NOT NULL, updated_at INTEGER NOT NULL ); CREATE TABLE IF NOT EXISTS posts ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL, author TEXT NOT NULL, level TEXT NOT NULL DEFAULT '', type TEXT NOT NULL, course TEXT NOT NULL DEFAULT '', title TEXT NOT NULL, body TEXT NOT NULL, replies INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS idx_posts_created ON posts(created_at); CREATE TABLE IF NOT EXISTS replies ( id TEXT PRIMARY KEY, post_id TEXT NOT NULL, user_id TEXT NOT NULL, author TEXT NOT NULL, level TEXT NOT NULL DEFAULT '', body TEXT NOT NULL, created_at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS idx_replies_post ON replies(post_id, created_at); CREATE TABLE IF NOT EXISTS lib_notes ( note_id TEXT PRIMARY KEY, kind TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'generating', score INTEGER NOT NULL DEFAULT 0, verified INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL ); CREATE TABLE IF NOT EXISTS lib_sections ( note_id TEXT NOT NULL, key TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (note_id, key) ); CREATE TABLE IF NOT EXISTS cases ( case_id TEXT PRIMARY KEY, name TEXT NOT NULL, citation TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'cited', data TEXT NOT NULL DEFAULT '', cited_in TEXT NOT NULL DEFAULT '[]', updated_at INTEGER NOT NULL ); CREATE TABLE IF NOT EXISTS reports ( id TEXT PRIMARY KEY, note_id TEXT NOT NULL, user_id TEXT NOT NULL, message TEXT NOT NULL, created_at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS idx_reports_created ON reports(created_at); CREATE TABLE IF NOT EXISTS course_edits ( id TEXT PRIMARY KEY, data TEXT NOT NULL, updated_at INTEGER NOT NULL ); CREATE TABLE IF NOT EXISTS quiz ( note_id TEXT PRIMARY KEY, data TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', updated_at INTEGER NOT NULL ); CREATE TABLE IF NOT EXISTS irac ( id TEXT PRIMARY KEY, data TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', chk TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL ); CREATE TABLE IF NOT EXISTS quiz_stat ( note_id TEXT PRIMARY KEY, attempts INTEGER NOT NULL DEFAULT 0, passes INTEGER NOT NULL DEFAULT 0, sumpct INTEGER NOT NULL DEFAULT 0, w0 INTEGER NOT NULL DEFAULT 0, w1 INTEGER NOT NULL DEFAULT 0, w2 INTEGER NOT NULL DEFAULT 0, w3 INTEGER NOT NULL DEFAULT 0, w4 INTEGER NOT NULL DEFAULT 0, w5 INTEGER NOT NULL DEFAULT 0, w6 INTEGER NOT NULL DEFAULT 0, w7 INTEGER NOT NULL DEFAULT 0, w8 INTEGER NOT NULL DEFAULT 0, w9 INTEGER NOT NULL DEFAULT 0, w10 INTEGER NOT NULL DEFAULT 0, w11 INTEGER NOT NULL DEFAULT 0, w12 INTEGER NOT NULL DEFAULT 0, w13 INTEGER NOT NULL DEFAULT 0, w14 INTEGER NOT NULL DEFAULT 0, w15 INTEGER NOT NULL DEFAULT 0, w16 INTEGER NOT NULL DEFAULT 0, w17 INTEGER NOT NULL DEFAULT 0, w18 INTEGER NOT NULL DEFAULT 0, w19 INTEGER NOT NULL DEFAULT 0, w20 INTEGER NOT NULL DEFAULT 0, w21 INTEGER NOT NULL DEFAULT 0, w22 INTEGER NOT NULL DEFAULT 0, w23 INTEGER NOT NULL DEFAULT 0, w24 INTEGER NOT NULL DEFAULT 0, w25 INTEGER NOT NULL DEFAULT 0, w26 INTEGER NOT NULL DEFAULT 0, w27 INTEGER NOT NULL DEFAULT 0, w28 INTEGER NOT NULL DEFAULT 0, w29 INTEGER NOT NULL DEFAULT 0 );

-- Optional student profile details (also created automatically when first used)
CREATE TABLE IF NOT EXISTS profile ( user_id TEXT PRIMARY KEY, phone TEXT NOT NULL DEFAULT '', uni TEXT NOT NULL DEFAULT '', yr TEXT NOT NULL DEFAULT '', sem TEXT NOT NULL DEFAULT '[]', name_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0, done INTEGER NOT NULL DEFAULT 0, terms_at INTEGER NOT NULL DEFAULT 0, tour_at INTEGER NOT NULL DEFAULT 0 );

-- The LawLink pass (also created automatically when first used)
CREATE TABLE IF NOT EXISTS kv ( k TEXT PRIMARY KEY, v TEXT NOT NULL DEFAULT '' );
CREATE TABLE IF NOT EXISTS pass ( user_id TEXT PRIMARY KEY, expires_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE IF NOT EXISTS codes ( code TEXT PRIMARY KEY, days INTEGER NOT NULL DEFAULT 30, batch TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, used_by TEXT, used_at INTEGER );

-- Card payments through Paystack (also created automatically when first used)
CREATE TABLE IF NOT EXISTS payments ( ref TEXT PRIMARY KEY, user_id TEXT NOT NULL, amount INTEGER NOT NULL, days INTEGER NOT NULL DEFAULT 30, status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL DEFAULT 0, paid_at INTEGER );
CREATE INDEX IF NOT EXISTS payments_user ON payments (user_id, created_at);

-- Announcements posted by the admin
CREATE TABLE IF NOT EXISTS announcements ( id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', link TEXT NOT NULL DEFAULT '', link_label TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, ends_at INTEGER NOT NULL DEFAULT 0 );
